                     ( "8d",   _("The last 8 days")),
                     ( "35d",  _("The last 35 days")),
                     ( "400d", _("The last 400 days")), ]


    def compute_range(self, rangespec):
        if rangespec == None:
            rangespec = "4h"

        # Compatibility with previous versions
        elif rangespec[0] == "pnp_view":
            rangespec = {
                1: "4h",
                2: "25h",
                3: "8d",
                4: "35d",
                5: "400d"
            }.get(rangespec[1], "4h")

